Here is the root cause:
The bug was caused by storing the IRQ value returned by `platform_get_irq_byname()` in an unsigned integer, which could lead to the loss of negative error codes. This means that if an error occurred while retrieving the IRQ, it would be incorrectly treated as a valid positive value, potentially causing the system to operate incorrectly or crash.

Here is the patch:

 static int aiu_probe(struct platform_device *pdev)
 {
 	struct device *dev = &pdev->dev;
 	void __iomem *regs;
 	struct regmap *map;
 	struct aiu *aiu;
 	int ret;

 	aiu = devm_kzalloc(dev, sizeof(*aiu), GFP_KERNEL);
 	if (!aiu)
 		return -ENOMEM;
 	platform_set_drvdata(pdev, aiu);

 	ret = device_reset(dev);
 	if (ret) {
 		if (ret != -EPROBE_DEFER)
 			dev_err(dev, "Failed to reset device\n");
 		return ret;
 	}

 	regs = devm_platform_ioremap_resource(pdev, 0);
 	if (IS_ERR(regs))
 		return PTR_ERR(regs);

 	map = devm_regmap_init_mmio(dev, regs, &aiu_regmap_cfg);
 	if (IS_ERR(map)) {
 		dev_err(dev, "failed to init regmap: %ld\n",
 			PTR_ERR(map));
 		return PTR_ERR(map);
 	}

 	aiu->i2s.irq = platform_get_irq_byname(pdev, "i2s");
-	if (aiu->i2s.irq < 0) {
-		dev_err(dev, "Can't get i2s irq\n");
+	if (aiu->i2s.irq < 0)
 		return aiu->i2s.irq;
-	}

 	aiu->spdif.irq = platform_get_irq_byname(pdev, "spdif");
-	if (aiu->spdif.irq < 0) {
-		dev_err(dev, "Can't get spdif irq\n");
+	if (aiu->spdif.irq < 0)
 		return aiu->spdif.irq;
-	}

 	ret = aiu_clk_get(dev);
 	if (ret)
 		return ret;

 	/* Register the cpu component of the aiu */
 	ret = snd_soc_register_component(dev, &aiu_cpu_component,
 					 aiu_cpu_dai_drv,
 					 ARRAY_SIZE(aiu_cpu_dai_drv));
 	if (ret) {
 		dev_err(dev, "Failed to register cpu component\n");
 		return ret;
 	}

 	/* Register the hdmi codec control component */
 	ret = aiu_hdmi_ctrl_register_component(dev);
 	if (ret) {
 		dev_err(dev, "Failed to register hdmi control component\n");
 		goto err;
 	}

 	/* Register the internal dac control component on gxl */
 	if (of_device_is_compatible(dev->of_node, "amlogic,aiu-gxl")) {
 		ret = aiu_acodec_ctrl_register_component(dev);
 		if (ret) {
 			dev_err(dev,
 			    "Failed to register acodec control component\n");
 			goto err;
 		}
 	}

 	return 0;
 err:
 	snd_soc_unregister_component(dev);
 	return ret;
 }



